"""Publish the verified Python repository lesson in the local media catalogue."""
from pathlib import Path
import json,html,hashlib,shutil
R=Path(__file__).resolve().parents[1];N='agent-sdk-python-github-tour';P=R/'presentations'/N;V=R/'videos'/N
report=json.loads((V/'validation.json').read_text(encoding='utf-8'));assert report['fullVideoAndAudioDecode']=='passed';assert hashlib.sha256((V/report['file']).read_bytes()).hexdigest()==report['sha256']
timeline=json.loads((V/'timeline.json').read_text(encoding='utf-8'));story=json.loads((P/'storyboard.json').read_text(encoding='utf-8'))
