sec=int(report['durationSeconds']);stamp=f'{sec//60}:{sec%60:02}'
catalog=R/'videos/index.html';body=catalog.read_text(encoding='utf-8');card=f'<article data-project="{N}"><span>CLAUDE AGENT SDK · PYTHON GITHUB TOUR</span><a href="{N}/index.html"><img loading="lazy" src="{N}/cover.png" alt="Explore the Python GitHub Repository"></a><div><h2>Python Learning Platform: GitHub Repository Tour</h2><p>Verified · {stamp} · 1080p · Real GitHub screenshots · First lesson and Python architecture</p><a href="{N}/{report["file"]}">MP4</a> · <a href="{N}/index.html">Player and chapters</a></div></article>'
